import networkx as nx
import itertools

def find_graph():
    for edges in itertools.combinations(itertools.combinations(range(9), 2), 9):
        G = nx.Graph()
        G.add_edges_from(edges)
        if all(degree >= 2 for degree in nx.degree_centrality(G).values()) and all(degree <= 3 for degree in nx.degree_centrality(G).values()) and 9 <= G.number_of_edges() <= 18 and nx.algorithms.coloring.greedy_color(G) <= 4 and nx.algorithms.coloring.greedy_color(G) >= 2 and (5, 6) in G.edges() and (2, 3) in G.edges():
            return list(G.edges())
    return "UNSATISFIABLE"

print(find_graph())
